contains

    real*8 function safe_log10(x)
        real*8, intent(in) :: x
        safe_log10 = log10(max(x, 1d-300))
    end function safe_log10

    ! Interval i (1-based, 1..n-1) holding x and its fraction f, x clamped to the axis
    subroutine locate(x, axis, i, f)
        real*8, intent(in) :: x, axis(:)
        integer, intent(out) :: i
        real*8, intent(out) :: f
        real*8 :: xc
        integer :: n

        n = size(axis)
        xc = min(max(x, axis(1)), axis(n))
        i = 1
        do while (i < n - 1 .and. axis(i + 1) < xc)
            i = i + 1
        end do
        f = (xc - axis(i))/(axis(i + 1) - axis(i))
    end subroutine locate

    real*8 function linear(x, axis, values)
        real*8, intent(in) :: x, axis(:), values(:)
        integer :: i
        real*8 :: f

        call locate(x, axis, i, f)
        linear = (1 - f)*values(i) + f*values(i + 1)
    end function linear

    ! z stored row-major [y][x]: z(j, i) is element (j - 1)*size(xs) + i
    real*8 function bilinear(x, y, xs, ys, z)
        real*8, intent(in) :: x, y, xs(:), ys(:), z(:)
        integer :: i, j, nx
        real*8 :: fx, fy, low, high

        nx = size(xs)
        call locate(x, xs, i, fx)
        call locate(y, ys, j, fy)
        low = (1 - fx)*z((j - 1)*nx + i) + fx*z((j - 1)*nx + i + 1)
        high = (1 - fx)*z(j*nx + i) + fx*z(j*nx + i + 1)
        bilinear = (1 - fy)*low + fy*high
    end function bilinear

    real*8 function co_lookup(table, tgas, lvg)
        real*8, intent(in) :: table(:), tgas, lvg
        co_lookup = bilinear(safe_log10(tgas), safe_log10(lvg + 1d-13), &
                             log10(co_t), co_log_neff, table)
    end function co_lookup

    real*8 function l0_co_interp1d(a0)
        real*8, intent(in) :: a0
        l0_co_interp1d = 10d0**(-linear(safe_log10(a0), log10(co_t), co_l0))
    end function l0_co_interp1d

    real*8 function llte_co_interp2d(a0, a1)
